/**
 * Contract test against the real Admin API. The samples are generated by
 * `pytest admin_api/tests/test_contract_samples.py` (one per endpoint) and committed here.
 * Every sample must parse with the schema the frontend uses for that endpoint.
 */
import { z } from "zod";
import {
  Alert,
  AlertFeedbackResponse,
  ApiError,
  AuditEntry,
  EndpointInventoryItem,
  Finding,
  LearningStatus,
  LoginResponse,
  Me,
  MetricsSummary,
  Paged,
  PurgeResponse,
  Rule,
  RuleTestResult,
  Scan,
  Settings,
  Timeseries,
  TrafficEvent,
  Upstream,
} from "@/api/schemas";

const schemaFor: Record<string, z.ZodTypeAny> = {
  auth_login: LoginResponse,
  me: Me,
  upstreams: z.array(Upstream),
  settings: Settings,
  settings_patch: Settings,
  metrics_summary_1h: MetricsSummary,
  metrics_summary_24h: MetricsSummary,
  metrics_summary_7d: MetricsSummary,
  metrics_timeseries_1h: Timeseries,
  metrics_timeseries_24h: Timeseries,
  metrics_timeseries_7d: Timeseries,
  traffic_recent: Paged(TrafficEvent),
  traffic_stream_event: TrafficEvent,
  rules: Paged(Rule),
  rule_create: Rule,
  rule_patch: Rule,
  rules_test: RuleTestResult,
  alerts: Paged(Alert),
  alert: Alert,
  alert_patch_acknowledged: AlertFeedbackResponse,
  alert_patch_false_positive: AlertFeedbackResponse,
  alert_promote: Rule,
  learning_status: LearningStatus,
  learning_patch: LearningStatus,
  learning_reset: LearningStatus,
  scan_start: Scan,
  scan: Scan,
  scan_failed: Scan,
  scans: Paged(Scan),
  scan_findings: Paged(Finding),
  finding_apply_rule: Finding,
  endpoints: Paged(EndpointInventoryItem),
  audit_log: Paged(AuditEntry),
  privacy_purge: PurgeResponse,
  error_401: ApiError,
  error_403: ApiError,
  error_404: ApiError,
  error_422: ApiError,
  error_502: ApiError,
};

const files = import.meta.glob("./contract/samples/*.json", { eager: true, import: "default" });
const samples = Object.fromEntries(
  Object.entries(files).map(([path, data]) => [path.split("/").pop()!.replace(/\.json$/, ""), data]),
);

describe("Admin API responses match the frontend contracts", () => {
  it("has a sample for every mapped endpoint and a schema for every sample", () => {
    expect(Object.keys(samples).sort()).toEqual(Object.keys(schemaFor).sort());
  });

  it.each(Object.keys(schemaFor))("%s", (name) => {
    const result = schemaFor[name].safeParse(samples[name]);
    if (!result.success) {
      const issues = result.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ");
      throw new Error(`${name}.json does not match its schema: ${issues}`);
    }
  });

  it("keeps error responses in the gateway's envelope", () => {
    for (const code of ["401", "403", "404", "422", "502"]) {
      expect(ApiError.parse(samples[`error_${code}`]).request_id).toBeTruthy();
    }
  });
});
